-- (b-i) moving average (real SQLite / PostgreSQL)
SELECT name, AVG(hours_studied) OVER (ORDER BY hours_studied DESC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS ma3 FROM developers;
-- (b-ii) peers within 100
SELECT name, COUNT(*) OVER (ORDER BY hours_studied RANGE BETWEEN 100 PRECEDING AND CURRENT ROW) AS peers FROM developers;
-- (b-iii) others-average per role (see lesson; needs EXCLUDE support)
-- (c) No hour ties → ROWS and RANGE agree on hours ordering; they diverge on tied orderings (e.g. the Japan country pair under country ordering, where ROWS would split the pair and RANGE keeps it whole).

